package ama.transcript;
import java.util.*;import java.lang.reflect.*;import ama.contract.TaskContracts.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
/** Pure metadata/fixed-input checks used by the private assembler; these rows mint no capability. */
class Task11PublicationExactRetryTest {
 static final String PUB="12345678-1234-4234-8234-123456789abc",FINAL="12345678-1234-4234-8234-123456789abd",TASK="12345678-1234-4234-8234-123456789abe",OP="12345678-1234-4234-8234-123456789abf",EXEC="12345678-1234-4234-8234-123456789ac0",MEETING="12345678-1234-4234-8234-123456789ac1";
 Map<String,Object> row(Object... values){var m=new HashMap<String,Object>();for(int i=0;i<values.length;i+=2)m.put((String)values[i],values[i+1]);return m;}
 TaskSpec spec(){return new TaskSpec("KNOWLEDGE_PUBLISH_V1","KNOWLEDGE_PUBLISH",new SubjectRef("MEETING",MEETING),"c".repeat(64),new TypedRef("PUBLICATION",PUB),"a".repeat(64),13,0,0,3);}
 Map<String,Object> header(){return row("id",PUB,"confirmation_id",FINAL,"business_key",PUB+":"+FINAL,"library_id","library","folder_id","folder","state","FAILED","revision",4L);}
 Map<String,List<Map<String,Object>>> rows(){var spec=spec();var r=new HashMap<String,List<Map<String,Object>>>();
  r.put("publication_submission",new ArrayList<>(List.of(row("task_id",TASK,"publication_id",PUB,"submission_no",1L,"confirmation_id",FINAL,"provider_id","provider","business_key",PUB+":"+FINAL,"library_id","library","folder_id","folder","requester_id","owner","logical_request_hash",spec.inputFingerprint(),"execution_request_hash","b".repeat(64),"local_state","UNDECIDED"))));
  r.put("durable_task",new ArrayList<>(List.of(row("id",TASK,"task_type",spec.type(),"pool",spec.pool(),"subject_kind","MEETING","subject_id",MEETING,"producer_key",spec.producerKey(),"input_kind","PUBLICATION","input_id",PUB,"input_fingerprint",spec.inputFingerprint(),"business_version",13L,"priority",0L,"cancel_epoch",0L,"max_attempts",3L,"attempt",1L,"state","FAILED","output_kind",null,"output_id",null))));
  r.put("task_attempt",new ArrayList<>(List.of(row("task_id",TASK,"attempt",1L,"ended_at","done","outcome","FAILED"))));
  r.put("external_operation",new ArrayList<>(List.of(row("id",OP,"operation_kind","KNOWLEDGE_PUBLISH","business_key",PUB+":"+FINAL,"subject_kind","MEETING","subject_id",MEETING,"request_hash",spec.inputFingerprint(),"current_execution_no",1L,"state","FAILED","external_result_present",0L,"reconcile_epoch",1L))));
  r.put("external_execution",new ArrayList<>(List.of(row("id",EXEC,"operation_id",OP,"execution_no",1L,"task_id",TASK,"request_hash","b".repeat(64),"state","FAILED","no_effect_basis","DEFINITIVE_REJECTION","marked_at","marked","task_attempt",1L,"no_effect_verified_at","verified","provider_proof_reference_shape",1L,"no_effect_evidence_present",1L))));
  r.put("publication_attempt",new ArrayList<>(List.of(row("id",EXEC,"publication_id",PUB,"confirmation_id",FINAL,"operation_id",OP,"execution_id",EXEC,"kind","PUBLISH","outcome","FAILED","finished_at","done"))));r.put("external_document_mapping",new ArrayList<>());return r;
 }
 PublicationGraph.Plan plan(Map<String,List<Map<String,Object>>> rows){return new PublicationGraph.Plan(MEETING,List.of(),List.of(),rows,new Task11AcceptanceBindingTest().budget());}
 Object selected(Map<String,List<Map<String,Object>>> rows,Map<String,Object> h,long expected)throws Exception {var method=assertDoesNotThrow(()->JdbcPublicationReplacement.class.getDeclaredMethod("exactSelection",PublicationGraph.Plan.class,Map.class,long.class),"Exact mode needs current remote-selected-round validation");method.setAccessible(true);return method.invoke(null,plan(rows),h,expected);}
 @Test void realMarkedCurrentRemoteFailureCanBeSelected()throws Exception {assertNotNull(selected(rows(),header(),1));}
 @Test void localUnmarkedAndUnknownCannotAuthorizeExactRetry()throws Exception {for(String field:List.of("marked_at","no_effect_basis","state","no_effect_verified_at","provider_proof_reference_shape")){var r=rows();r.get("external_execution").getFirst().put(field,switch(field){case "no_effect_basis"->"NOT_SENT";case "state"->"UNKNOWN";case "provider_proof_reference_shape"->0L;default->null;});assertThrows(InvocationTargetException.class,()->selected(r,header(),1),field);}var r=rows();r.get("publication_submission").getFirst().put("local_state","NEVER_MARKED");assertThrows(InvocationTargetException.class,()->selected(r,header(),1));}
 @Test void staleExpectedAndOverflowAreConflictRatherThanMissingProvenance()throws Exception {for(long expected:List.of(2L,9223372036854775806L)){var error=assertThrows(InvocationTargetException.class,()->selected(rows(),header(),expected));assertInstanceOf(ama.contract.TranscriptContracts.Failure.class,error.getCause());assertEquals(409,((ama.contract.TranscriptContracts.Failure)error.getCause()).status());}}
 @Test void selectedRoundMustBeCurrentOperationAndLatestAcceptedSubmission()throws Exception {for(String table:List.of("external_operation","external_execution","publication_submission")){var r=rows();r.get(table).add(new HashMap<>(r.get(table).getFirst()));assertThrows(InvocationTargetException.class,()->selected(r,header(),1),table);}var r=rows();r.get("external_operation").getFirst().put("state","MANUAL_REQUIRED");assertThrows(InvocationTargetException.class,()->selected(r,header(),1));var h=header();h.put("confirmation_id",PUB);assertThrows(InvocationTargetException.class,()->selected(rows(),h,1));}
 void fixed(TaskSpec old,TaskSpec next,Map<String,Object> before,Map<String,Object> after)throws Exception {var method=assertDoesNotThrow(()->JdbcPublicationReplacement.class.getDeclaredMethod("sameFixedInput",TaskSpec.class,TaskSpec.class,Map.class,Map.class),"Private exact path must preserve every generic fixed-input invariant");method.setAccessible(true);method.invoke(null,old,next,before,after);}
 Map<String,Object> manifest(){var m=new HashMap<String,Object>();for(String k:List.of("schema","providerId","storeInstanceId","clientId","delegationKeyId","assertionKeyId","publicationId","confirmationId","requesterId","businessKey","libraryId","folderId","logicalRequestHash","payloadSha256","archiveIndexSha256","renderArtifact","meetingId","businessVersion","cancelEpoch"))m.put(k,k);return m;}
 @Test void onlyProducerAndNewExecutionEnvelopeMayChange()throws Exception {var old=spec();var next=new TaskSpec(old.type(),old.pool(),old.subject(),"d".repeat(64),old.input(),old.inputFingerprint(),old.businessVersion(),old.priority(),old.cancelEpoch(),old.maxAttempts());var before=manifest();var after=new HashMap<>(before);after.put("executionNo",2L);after.put("submissionNo",2L);after.put("priorProofs",List.of("authenticated"));after.put("acceptanceBinding",Map.of("operation","PUBLICATION_ZERO_EFFECT_RETRY"));fixed(old,next,before,after);for(String key:before.keySet()){var changed=new HashMap<>(after);changed.put(key,"changed");assertThrows(InvocationTargetException.class,()->fixed(old,next,before,changed),key);}}
 @Test void allTaskFixedFieldsRemainEqual()throws Exception {var old=spec();for(var changed:List.of(new TaskSpec("OTHER",old.pool(),old.subject(),"d".repeat(64),old.input(),old.inputFingerprint(),13,0,0,3),new TaskSpec(old.type(),"OTHER",old.subject(),"d".repeat(64),old.input(),old.inputFingerprint(),13,0,0,3),new TaskSpec(old.type(),old.pool(),new SubjectRef("MEETING",PUB),"d".repeat(64),old.input(),old.inputFingerprint(),13,0,0,3),new TaskSpec(old.type(),old.pool(),old.subject(),"d".repeat(64),new TypedRef("PUBLICATION",FINAL),old.inputFingerprint(),13,0,0,3),new TaskSpec(old.type(),old.pool(),old.subject(),"d".repeat(64),old.input(),"e".repeat(64),13,0,0,3),new TaskSpec(old.type(),old.pool(),old.subject(),"d".repeat(64),old.input(),old.inputFingerprint(),14,0,0,3),new TaskSpec(old.type(),old.pool(),old.subject(),"d".repeat(64),old.input(),old.inputFingerprint(),13,1,0,3),new TaskSpec(old.type(),old.pool(),old.subject(),"d".repeat(64),old.input(),old.inputFingerprint(),13,0,1,3),new TaskSpec(old.type(),old.pool(),old.subject(),"d".repeat(64),old.input(),old.inputFingerprint(),13,0,0,4))){assertThrows(InvocationTargetException.class,()->fixed(old,changed,manifest(),manifest()),changed.toString());}}
 @Test void canonicalManifestCountersAreEqualAcrossParsedIntegerAndConstructedLong()throws Exception {var before=manifest();var after=new HashMap<>(before);before.put("businessVersion",13);before.put("cancelEpoch",0);after.put("businessVersion",13L);after.put("cancelEpoch",0L);assertDoesNotThrow(()->fixed(spec(),spec(),before,after));}
 @Test void earlierSealedLocalSubmissionDoesNotChangeRemoteExecutionOrdinal()throws Exception {var r=rows();var remote=r.get("publication_submission").getFirst();var local=new HashMap<>(remote);String localTask="12345678-1234-4234-8234-123456789ac2";local.put("task_id",localTask);local.put("local_state","NEVER_MARKED");local.put("local_decided_at","done");local.put("local_decided_by","owner");local.put("local_reason","TERMINAL_UNMARKED_FAILURE");local.put("local_attempt_no",0L);local.put("local_execution_id",null);remote.put("submission_no",2L);r.get("publication_submission").add(local);var task=new HashMap<>(r.get("durable_task").getFirst());task.put("id",localTask);task.put("producer_key","d".repeat(64));task.put("attempt",0L);r.get("durable_task").add(task);assertNotNull(selected(r,header(),1));}
}
